        await SearchTermChanged.InvokeAsync(value);
    }
}

@page "/board"
@namespace sv_58bbb3c645d4478c9ab7ecebb025587e.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Project Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <BoardStats Total="tasks.Count"
                TodoCount="TodoTasks.Count"
                InProgressCount="InProgressTasks.Count"
                DoneCount="DoneTasks.Count"
                OverdueCount="tasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="OnSearchChanged" />

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do"
                      Status="To Do"
                      Tasks="FilteredTodo"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveRight="MoveRight"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn ColumnName="In Progress"
                      Status="In Progress"
                      Tasks="FilteredInProgress"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveLeft="MoveLeft"
                      OnMoveRight="MoveRight"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn ColumnName="Done"
                      Status="Done"
                      Tasks="FilteredDone"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveLeft="MoveLeft"
                      OnAddTask="HandleAddTask" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchTerm = "";
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private List<TaskItem> TodoTasks => tasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => tasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => tasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> FilteredTodo => ApplyFilter(TodoTasks);
    private List<TaskItem> FilteredInProgress => ApplyFilter(InProgressTasks);
    private List<TaskItem> FilteredDone => ApplyFilter(DoneTasks);

    private List<TaskItem> ApplyFilter(List<TaskItem> source) =>
        string.IsNullOrWhiteSpace(searchTerm)
            ? source
            : source.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void OnSearchChanged(string value) => searchTerm = value;

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex <= 0) return;
        var newStatus = Statuses[currentIndex - 1];
        await UpdateStatus(task, newStatus);
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex >= Statuses.Length - 1) return;
        var newStatus = Statuses[currentIndex + 1];
        await UpdateStatus(task, newStatus);
    }

    private async Task UpdateStatus(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                tasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(AddTaskForm.NewTaskModel model)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            tasks.Add(created with { Status = model.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

